        "maxFileSizeBytes": 536870912,
        "query": "SELECT\n  s.id AS sessionId,\n  CAST(strftime('%s', s.created_at) * 1000 AS INTEGER) AS timestamp,\n  COALESCE(NULLIF(CASE WHEN json_valid(s.model_config_json) = 1 THEN json_extract(s.model_config_json, '$.model_name') END, ''), 'unknown') AS model,\n  'unknown' AS project,\n  CAST(COALESCE(s.accumulated_input_tokens, s.input_tokens, 0) AS INTEGER) AS inputTokens,\n  0 AS cachedInputTokens,\n  0 AS cacheCreationInputTokens,\n  CAST(COALESCE(s.accumulated_output_tokens, s.output_tokens, 0) AS INTEGER) AS outputTokens,\n  CAST(MAX(0, COALESCE(s.accumulated_total_tokens, s.total_tokens, 0) - COALESCE(s.accumulated_input_tokens, s.input_tokens, 0) - COALESCE(s.accumulated_output_tokens, s.output_tokens, 0)) AS INTEGER) AS reasoningOutputTokens\nFROM sessions s\nWHERE json_valid(s.model_config_json) = 1\n  AND trim(json_extract(s.model_config_json, '$.model_name')) <> ''\n  AND (COALESCE(s.accumulated_total_tokens, s.total_tokens, 0) > 0\n       OR COALESCE(s.accumulated_input_tokens, s.input_tokens, 0) > 0\n       OR COALESCE(s.accumulated_output_tokens, s.output_tokens, 0) > 0)\nORDER BY timestamp DESC, s.rowid DESC"
