        "maxFileSizeBytes": 536870912,
        "query": "SELECT\n  CAST(ws.id AS TEXT) AS sessionId,\n  CASE\n    WHEN typeof(ws.createdAt) IN ('integer', 'real') THEN CAST(CASE WHEN ws.createdAt < 100000000000 THEN ws.createdAt * 1000 ELSE ws.createdAt END AS INTEGER)\n    WHEN ws.createdAt GLOB '[0-9]*' AND ws.createdAt NOT GLOB '*[^0-9]*' THEN CAST(CASE WHEN CAST(ws.createdAt AS NUMERIC) < 100000000000 THEN CAST(ws.createdAt AS NUMERIC) * 1000 ELSE CAST(ws.createdAt AS NUMERIC) END AS INTEGER)\n    ELSE CAST(strftime('%s', ws.createdAt) * 1000 AS INTEGER)\n  END AS timestamp,\n  COALESCE(NULLIF(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.model') END, ''), 'unknown') AS model,\n  'unknown' AS project,\n  CAST(COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.prompt_tokens') END, 0) AS INTEGER) AS inputTokens,\n  0 AS cachedInputTokens,\n  0 AS cacheCreationInputTokens,\n  CAST(COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.completion_tokens') END, 0) AS INTEGER) AS outputTokens,\n  CAST(MAX(0, COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.total_tokens') END, 0) - COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.prompt_tokens') END, 0) - COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.completion_tokens') END, 0)) AS INTEGER) AS reasoningOutputTokens\nFROM workspace_chats ws\nWHERE COALESCE(ws.include, 1) = 1\n  AND json_valid(ws.response) = 1\n  AND (COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.prompt_tokens') END, 0) > 0\n       OR COALESCE(CASE WHEN json_valid(ws.response) = 1 THEN json_extract(ws.response, '$.metrics.completion_tokens') END, 0) > 0)\nORDER BY timestamp DESC, ws.rowid DESC"
